        return false, why(res)
    end
    local hold = DIG.PERFECT + (math.random() - 0.5) * 0.04
    local took = os.clock() - t0
    if took <= 0.4 then DIG.rtt = DIG.rtt and (DIG.rtt * 0.7 + took * 0.3) or took end
    local rtt = (took <= 0.4) and took or (DIG.rtt or 0.15)
    local left = hold - rtt
    if left > 0 then task.wait(left) end
    fire("DigAction", "Release", res.session, hold)
    local t1 = os.clock()
    while RUNNING and not DIG.res and os.clock() - t1 < 4 do task.wait(0.05) end
    if DIG.res and DIG.res.ok ~= false then return true, isl end
    return false, "No reward"
end
function DIG.checkStop()
