local FISH = { last = "-" }
function FISH.spot()
    local map = Workspace:FindFirstChild("Map"); if not map then return nil end
    local r = hrp(); local from = r and r.Position or Vector3.zero
    local best, bd, bc
    for _, f in ipairs(map:GetChildren()) do
        local head, c = f:GetAttribute("DockHead"), f:GetAttribute("Center")
        if typeof(head) == "Vector3" and typeof(c) == "Vector3" then
            local d = (head - from).Magnitude
            if not bd or d < bd then best, bd, bc = head, d, c end
        end
    end
    if not best then return nil end
    local out = (best - bc) * Vector3.new(1, 0, 1)
    out = out.Magnitude > 0 and out.Unit or Vector3.new(0, 0, 1)
    local stand = best - out * 2 + Vector3.new(0, 3.2, 0)
    return stand, stand + out * 10
end
function FISH.once()
    local h = hum(); if not h or h.Health <= 0 then return false, "Respawning" end
    if not G.equip("Rod") then
        SHOP.rod(); task.wait(0.5)
        if not G.equip("Rod") then return false, "No rod" end
    end
    if (tonumber(lp:GetAttribute("Bait")) or 0) <= 0 then
        if on("fs_bait") then SHOP.bait() end
        if (tonumber(lp:GetAttribute("Bait")) or 0) <= 0 then return false, "Out of bait" end
    end
    if val("fs_spot", "Nearest Dock") == "Nearest Dock" then
        local r = hrp(); local spot, look = FISH.spot()
        if spot and r and (r.Position - spot).Magnitude > 8 then tp(spot, look); task.wait(0.5) end
    end
    if h.SeatPart then pcall(function() h.Sit = false end); task.wait(0.2) end
    if h:GetState() == Enum.HumanoidStateType.Swimming then return false, "Get out of the water" end
    G.equip("Rod")
    local t0 = os.clock()
    local res = inv("FishRequest", "Cast", 0.92 + math.random() * 0.08)
    if not okRes(res) then return false, why(res) end
    local list = {}
    for _, f in ipairs(type(res.fish) == "table" and res.fish or {}) do
        local d = Cfg.Fish and Cfg.Fish[f.id]
        list[#list + 1] = { i = f.i, id = f.id, r = d and RANK[d.Rarity] or 0, p = d and d.Price or 0 }
    end
    table.sort(list, function(a, b) if a.r ~= b.r then return a.r > b.r end return a.p > b.p end)
    local picks = {}
    for k = 1, math.min(tonumber(res.hooks) or 3, #list) do picks[#picks + 1] = list[k].i end
    local minT = ((Cfg.Fishing and Cfg.Fishing.MinTime) or 2.5) + 1.4 + num("fs_delay", 0)
    while RUNNING and os.clock() - t0 < minT do task.wait(0.1) end
    local fin = inv("FishRequest", "Finish", res.session, picks)
    if not okRes(fin) then return false, why(fin) end
    local got = type(fin.fish) == "table" and fin.fish or {}
    S.st.fish = S.st.fish + #got
    local top
    for _, id in ipairs(got) do
        local d = Cfg.Fish and Cfg.Fish[id]
        if d and (not top or (RANK[d.Rarity] or 0) > (RANK[top.Rarity] or 0)) then top = d end
    end
    FISH.last = top and (top.Rarity .. " " .. tostring(top.Name)) or "Nothing"
    if top and W.want("Fish") then W.send("Catch", top.Rarity .. " " .. tostring(top.Name), top.Rarity) end
    if type(fin.egg) == "string" then
        S.st.seaEggs = S.st.seaEggs + 1
        notify(L["Sea egg · "] .. G.name(fin.egg))
        if W.want("Egg") then W.send("Sea egg!", G.name(fin.egg) .. " egg", G.rarOf(fin.egg)) end
    end
    return true, FISH.last
end
function FISH.loop()
    local fails = 0
