local NEST = { ev = nil, home = nil, wait = {} }
function NEST.model(id)
    local f = Workspace:FindFirstChild("FTD_Nests")
    for _, m in ipairs(f and f:GetChildren() or {}) do
        if m:GetAttribute("Id") == id then return m end
    end
