end
function NEST.homeSpot()
    local map = Workspace:FindFirstChild("Map")
    local rs = map and map:FindFirstChild("Ranches")
    local ranch = rs and rs:FindFirstChild("Ranch" .. tostring(lp:GetAttribute("RanchId") or ""))
    local sp = ranch and ranch:FindFirstChild("OwnerSpawn")
    if sp and sp:IsA("BasePart") then NEST.home = sp.Position + Vector3.new(0, 3.5, 0); return NEST.home end
    local pz = map and map:FindFirstChild("Plaza")
    local ms = pz and pz:FindFirstChild("MainSpawn")
    if ms and ms:IsA("BasePart") then NEST.home = NEST.home or (ms.Position + Vector3.new(0, 3.5, 0)) end
    return NEST.home
end
function NEST.escape()
    local p = NEST.homeSpot()
    if p then tp(p) return end
    local c = Cfg.Zones and Cfg.Zones.Home and Cfg.Zones.Home.Center
    if c then stream(c); land(c) end
end
function NEST.hop(id, nest, dist, mom)
    local map = Workspace:FindFirstChild("Map")
    local f = map and map:FindFirstChild(id)
    local c = f and f:GetAttribute("Center")
    if typeof(c) ~= "Vector3" then c = Cfg.Zones and Cfg.Zones[id] and Cfg.Zones[id].Center end
    local base = (typeof(c) == "Vector3") and ((c - nest) * Vector3.new(1, 0, 1)) or Vector3.new(1, 0, 0)
    base = base.Magnitude > 1 and base.Unit or Vector3.new(1, 0, 0)
    local away = mom and ((nest - mom) * Vector3.new(1, 0, 1)) or nil
    away = (away and away.Magnitude > 1) and away.Unit or nil
    local best, bs, first
    for _, deg in ipairs({ 0, 30, -30, 60, -60, 90, -90, 120, -120, 150, -150, 180 }) do
        local d = CFrame.Angles(0, math.rad(deg), 0):VectorToWorldSpace(base)
        local p = nest + d * dist
        local g, wet = groundAt(p)
        first = first or Vector3.new(p.X, math.max(nest.Y, 4) + 3.2, p.Z)
        if g and not wet then
            local score = math.abs(deg) / 180 - (away and d:Dot(away) * 1.5 or 0)
            if not bs or score < bs then best, bs = g + Vector3.new(0, 3.2, 0), score end
        end
    end
    return best or first
end
function NEST.mom(id)
    local f = Workspace:FindFirstChild("FTD_NestMothers")
    for _, m in ipairs(f and f:GetChildren() or {}) do
        if m:GetAttribute("Nest") == id then
            local ok, cf = pcall(m.GetPivot, m)
            if ok then return cf.Position end
        end
    end
    return nil
end
function NEST.glide(id, nest, leash)
    local target = NEST.hop(id, nest, leash + 45, NEST.mom(id))
    local dir = (target - nest) * Vector3.new(1, 0, 1)
    dir = dir.Magnitude > 1 and dir.Unit or Vector3.new(1, 0, 0)
    local t0 = os.clock()
    while RUNNING and os.clock() - t0 < 12 do
        if NEST.ev and NEST.ev.kind ~= "Stole" then return end
        local r = hrp(); if not r then return end
        if ((r.Position - nest) * Vector3.new(1, 0, 1)).Magnitude < leash + 35 then
            local p = r.Position + dir * 7
            local g, wet = groundAt(p)
            local y = (g and not wet and math.abs(g.Y + 3.2 - r.Position.Y) < 12) and (g.Y + 3.2) or r.Position.Y
            r.AssemblyLinearVelocity = Vector3.zero
            r.CFrame = CFrame.lookAt(Vector3.new(p.X, y, p.Z), Vector3.new(p.X, y, p.Z) + dir)
        end
        task.wait(0.1)
    end
end
function NEST.firePrompt(p)
    if type(fireproximityprompt) == "function" then
        local ok = pcall(fireproximityprompt, p)
        if ok then return end
    end
    pcall(function() p:InputHoldBegin() end)
    task.wait((p.HoldDuration or 0) + 0.15)
    pcall(function() p:InputHoldEnd() end)
end
function NEST.waitEv(kinds, t)
    local t0 = os.clock()
    while RUNNING and os.clock() - t0 < t do
        if NEST.ev and kinds[NEST.ev.kind] then return NEST.ev end
        task.wait(0.05)
    end
    return nil
end
function NEST.try(id)
    local site = Cfg.Nests and Cfg.Nests.Sites and Cfg.Nests.Sites[id]
    if not site then return false, "No nest" end
    NEST.homeSpot()
    local r0 = hrp()
    local farAway = not r0 or (r0.Position - site.Pos).Magnitude > 400
    if farAway then
        setText(UI.nsState, L["Nest · going to "] .. id)
        land(site.Pos + Vector3.new(0, 0, 18), site.Pos)
        task.wait(1.5)
    end
    local m
    for _ = 1, 30 do m = NEST.model(id); if m then break end; task.wait(0.15) end
    if not m then NEST.wait[id] = os.clock() + 30; return false, "Nest not loaded" end
    local rar = m:GetAttribute("Rarity") or "Common"
    local pick = msel("ns_rar")
    if pick and not pick[rar] then
        local ra = tonumber(m:GetAttribute("RefreshAt"))
        NEST.wait[id] = (ra and ra > G.now()) and (os.clock() + (ra - G.now()) + 2) or (os.clock() + 120)
        return false, "Skipped " .. rar
    end
    local center = m:FindFirstChild("NestCenter")
    local prompt = center and center:FindFirstChildOfClass("ProximityPrompt")
    if not prompt then NEST.wait[id] = os.clock() + 20; return false, "No egg to take" end
    local cpos = center:IsA("BasePart") and center.Position or m:GetPivot().Position
    local t1 = os.clock()
    while RUNNING and on("ns_on") and os.clock() - t1 < 15 do
        local mp = NEST.mom(id)
        if not mp or ((mp - cpos) * Vector3.new(1, 0, 1)).Magnitude > 10 then break end
        setText(UI.nsState, L["Nest · waiting for mother"])
        task.wait(0.4)
    end
    land(cpos + Vector3.new(0, 0, 4), cpos)
    task.wait(0.15)
    NEST.ev = nil
    NEST.firePrompt(prompt)
    local ev = NEST.waitEv({ Stole = true, Caught = true, Dropped = true }, (prompt.HoldDuration or 0) + 3)
    if not ev or ev.kind ~= "Stole" then task.wait(1.5); return false, "Mother is guarding" end
    local leash = tonumber(ev.c) or tonumber(m:GetAttribute("Leash")) or 210
    setText(UI.nsState, L["Nest · escaping"])
    NEST.glide(id, site.Pos, leash)
    local done = NEST.waitEv({ Escaped = true, Caught = true, Dropped = true }, 5)
    if done and done.kind == "Escaped" then return true, G.name(done.a) end
    return false, done and done.kind or "Lost it"
end
function NEST.loop()
    while RUNNING do
        if on("ns_on") and alive() and not S.bossWant and G.eggsFull() then
            setText(UI.nsState, L["Nests · egg bag full ("] .. tostring(S.eggCap) .. ")")
            task.wait(3)
        elseif on("ns_on") and alive() and not S.bossWant then
            local did = false
            local sites = msel("ns_sites")
            local maxEggs = (Cfg.Nests and Cfg.Nests.Eggs) or 4
            local order = {}
            local r = hrp()
            for _, id in ipairs((Cfg.Nests and Cfg.Nests.Order) or {}) do
                local st = Cfg.Nests.Sites and Cfg.Nests.Sites[id]
                if st and (not sites or sites[id]) then order[#order + 1] = { id = id, d = r and (r.Position - st.Pos).Magnitude or 0 } end
            end
            table.sort(order, function(a, b) return a.d < b.d end)
            for _, o in ipairs(order) do
                local id = o.id
                local tries = 0
                while RUNNING and on("ns_on") and not S.bossWant and not G.eggsFull() and tries < 8 and (NEST.wait[id] or 0) < os.clock()
                    and (tonumber(lp:GetAttribute("Nest_" .. id)) or 0) < maxEggs do
                    tries = tries + 1
                    if not claimWait("nest", 20) then break end
                    local ok, info = NEST.try(id)
                    free("nest")
                    did = true
                    setText(UI.nsState, (ok and L["Got · "] or "Nest · ") .. G.short(info, 22))
                    task.wait(ok and 0.4 or 1.2)
                end
                if did then break end
            end
            if not did then
                local soon
                for _, id in ipairs((Cfg.Nests and Cfg.Nests.Order) or {}) do
                    if (not sites or sites[id]) then
                        local m = NEST.model(id)
                        local ra = m and tonumber(m:GetAttribute("RefreshAt"))
                        if ra and (not soon or ra < soon) then soon = ra end
                    end
                end
                setText(UI.nsState, soon and (L["Nests · refill in "] .. G.clock(soon - G.now())) or L["Nests · all taken"])
            end
            task.wait(2)
        else
            task.wait(0.5)
        end
    end
end
track(Remotes:WaitForChild("NestEvent").OnClientEvent:Connect(function(kind, a, b, c)
