local BOSS = { hover = nil, lastThrow = 0, state = nil, claimed = {} }
function BOSS.attack(t, rt)
    if not rt or rt > t then
        local v = t - 7
        if v < 0 then return nil, 0 end
        local n = math.floor(v / 16); local w = v - n * 16
        local kind = (n % 2 == 0) and "surge" or "leap"
        local dur = kind == "leap" and MB.LeapTime or MB.SurgeTime
        if w < dur then return kind, w / dur end
        return nil, 0
    end
    local v = t - rt
    if v < MB.RageRoarTime then return "rage", v / MB.RageRoarTime end
    v = v - MB.RageRoarTime
    local n = math.floor(v / 11); local w = v - n * 11
    local kind = (n % 2 == 0) and "leap" or "surge"
    local dur = kind == "leap" and MB.LeapTime or MB.SurgeTime
    if 11 - dur <= w then return kind, (w - (11 - dur)) / dur end
    return nil, 0
end
function BOSS.pose()
    if not MB or FTD:GetAttribute("BossState") ~= "Fight" then return nil end
    local start, c = FTD:GetAttribute("BossStart"), FTD:GetAttribute("BossCenter")
    if not start or typeof(c) ~= "Vector3" then return nil end
    local t = G.now() - start - MB.IntroTime
    local ra = FTD:GetAttribute("BossRageAt")
    local rt = ra and (ra - start - MB.IntroTime) or nil
    local w = 2 * math.pi / MB.Lap
    local raging = rt and rt < t
    local a = raging and (rt * w + (t - rt) * w * MB.RageSpeed) or t * w
    local pos = c + Vector3.new(math.cos(a) * MB.Radius, 0, math.sin(a) * MB.Radius)
    local dir = Vector3.new(-math.sin(a), 0, math.cos(a))
    local yaw = math.atan2(-dir.X, -dir.Z)
    local s = math.clamp(math.min(1, t / 2.5), 0, 1)
    local y = math.sin(t * 0.85) * 1.3 - 2.95 - (1 - s * s * (3 - s * 2)) * 14
    local pitch = math.sin(t * 0.85 + 1.2) * 3
    local roll = -14
    local k, p = BOSS.attack(t, rt)
    if k == "surge" or k == "rage" then
        local sn = math.sin(math.pi * p); local m = k == "rage" and 1.35 or 1
        y = y + sn * 9 * m; pitch = pitch + sn * 22 * m; roll = roll * (1 - sn)
    elseif k == "leap" then
        local hgt = raging and 38 or 32
        y = y + (4 * hgt * p * (1 - p) + math.sin(math.pi * p) * 10)
        local spd = MB.Radius * w * (raging and MB.RageSpeed or 1) * 1.6
        pitch = math.deg(math.atan2(4 * hgt * (1 - 2 * p) / MB.LeapTime, spd))
        roll = (1 - math.sin(math.pi * p)) * -14 + math.sin(math.pi * p) * 20
    end
    return CFrame.new(pos.X, y, pos.Z) * CFrame.Angles(0, yaw, 0) * CFrame.Angles(math.rad(pitch), 0, 0) * CFrame.Angles(0, 0, math.rad(roll))
end
function BOSS.eggSpots(p)
    local out = {}
    local n = (MB and MB.Eggs) or 5
    for i = 1, n do
        local a = i / n * math.pi * 2 + 0.4
        local r = i % 2 * 8 + 14
        out[#out + 1] = Vector3.new(p.X + math.cos(a) * r, 0.25, p.Z + math.sin(a) * r)
    end
    return out
end
function BOSS.throw()
    local pose = BOSS.pose(); if not pose then return false end
    local c = lp.Character; if not c then return false end
    local spear = c:FindFirstChild("BossSpear")
    if not (spear and spear:IsA("Tool")) then spear = G.equip("BossSpear") end
    if not spear then return false end
    local r = hrp()
    if not r or (r.Position - pose.Position).Magnitude > ((MB.Range or 320) - 10) then return false end
    local off = Vector3.new((math.random() - 0.5) * MB.Half.X * 0.5, (math.random() - 0.3) * MB.Half.Y * 0.4, -MB.Half.Z * (0.7 + math.random() * 0.2))
    fire("BossEvent", "Throw", pose:PointToWorldSpace(off), off)
    BOSS.lastThrow = os.clock()
    return true
end
function BOSS.loop()
    while RUNNING do
        local st = FTD:GetAttribute("BossState")
        if st ~= BOSS.state then
            if (st == "Intro" or st == "Fight") and on("bs_notify") and BOSS.state ~= "Intro" then
                notify(L["Mosasaurus is attacking!"])
                if W.want("Boss") then W.send("Boss", "Mosasaurus fight started") end
            end
            BOSS.state = st
        end
        local fighting = on("bs_on") and MB and (st == "Fight" or st == "Intro") and alive()
        local claiming = on("bs_on") and on("bs_claim") and MB and st == "Death" and tostring(FTD:GetAttribute("BossEggs") or "") ~= "" and alive()
        if fighting or claiming then
            S.bossWant = true
            local t0 = os.clock()
            while S.lock and S.lock ~= "boss" and os.clock() - t0 < 4 do task.wait(0.1) end
            S.lock, S.lockAt = "boss", os.clock()
            local c = FTD:GetAttribute("BossCenter")
            if typeof(c) ~= "Vector3" then c = MB.Center end
            if fighting then
                BOSS.hover = c + Vector3.new(0, num("bs_height", 60), 0)
                if st == "Fight" and os.clock() - BOSS.lastThrow >= (MB.ThrowCooldown or 1.3) + 0.08 then BOSS.throw() end
                local hp, mx = tonumber(FTD:GetAttribute("BossHP")) or 0, tonumber(FTD:GetAttribute("BossMaxHP")) or 1
                setText(UI.bsState, string.format(L["Boss · %d%% · my dmg %s"], math.floor(hp / math.max(1, mx) * 100), G.money(lp:GetAttribute("BossDamage") or 0)))
                task.wait(0.1)
            else
                local dcf = FTD:GetAttribute("BossDeathCF")
                local key = tostring(FTD:GetAttribute("BossStart"))
                if typeof(dcf) == "CFrame" and not BOSS.claimed[key] then
                    BOSS.claimed[key] = true
                    setText(UI.bsState, L["Boss · grabbing eggs"])
                    for _, p in ipairs(BOSS.eggSpots(dcf.Position)) do
                        if not RUNNING then break end
                        BOSS.hover = p + Vector3.new(0, 3, 0)
                        task.wait(0.7)
                    end
                end
                BOSS.hover = nil
                task.wait(0.5)
            end
        else
            if S.bossWant then
                S.bossWant = false
                BOSS.hover = nil
                free("boss")
                if on("bs_on") then NEST.escape() end
            end
            if UI.bsState then
                if st == "Idle" or not st then
                    local start = tonumber(FTD:GetAttribute("BossStart"))
                    local nxt = start and MB and (start + MB.Interval - G.now()) or nil
                    setText(UI.bsState, (nxt and nxt > 0) and (L["Boss · next ~"] .. G.clock(nxt)) or L["Boss · waiting"])
                else
                    setText(UI.bsState, L["Boss · "] .. tostring(st))
                end
            end
            task.wait(0.5)
        end
    end
end
track(Remotes:WaitForChild("BossEvent").OnClientEvent:Connect(function(kind, data)
    if kind == "Result" and type(data) == "table" then
        S.st.boss = S.st.boss + 1
        notify(L["Boss reward · +"] .. tostring(data.coins or 0) .. L[" coins"])
    elseif kind == "Egg" then
        notify(L["Boss egg!"])
        if W.want("Boss") then W.send("Boss egg", "Mosasaurus dropped an egg") end
    end
end))
local DINO = { lastHatch = "-", usedEgg = {} }
function DINO.after(c)
    if type(c) ~= "table" or not c.Id then return end
    local rar = G.rarOf(c.Species)
    DINO.lastHatch = rar .. " " .. G.name(c.Species)
    if W.want("Hatch") then W.send("Hatched", rar .. " " .. G.name(c.Species) .. (tonumber(c.Frac) and tonumber(c.Frac) >= 0.85 and " (Giant)" or ""), rar) end
    local mode = val("ht_after", "Ranch if room")
    if mode == "Leave it" then return end
    task.wait(0.4)
    local act = (mode == "Ranch if room" and G.placedCount() < (Cfg.RanchCapacity or 8)) and L["Place"] or "Store"
    inv("RanchRequest", act, c.Id)
end
function DINO.trade()
    if G.eggsFull() then return end
    local pick = msel("eg_rar")
    for sp, n in pairs(G.fossils()) do
        local c = Cfg.Creatures and Cfg.Creatures[sp]
        if c and not c.Marine and not c.Hybrid and (not pick or pick[c.Rarity]) and n >= G.need(sp) then
            local res = inv("LabRequest", "Trade", sp)
            if okRes(res) then
                S.st.eggs = S.st.eggs + 1
                if W.want("Egg") then W.send("New egg", G.name(sp) .. " egg", c.Rarity) end
                task.wait(0.3)
            else
                SHOP.at["trade_" .. sp] = os.clock() + 60
            end
        end
    end
end
function DINO.incubate()
    local inc, unl = G.json(L["Incubators"], {}), G.json("IncUnlocked", {})
    local eggs = G.json("Eggs", {})
    local pick = msel("in_rar")
    local fastest = val("in_order", "Rarest first") == "Fastest first"
    local list = {}
    for _, e in ipairs(eggs) do
        if e.Id and not DINO.usedEgg[e.Id] and (not pick or pick[G.rarOf(e.Species)]) then list[#list + 1] = e end
    end
    table.sort(list, function(a, b)
        local ra, rb = RANK[G.rarOf(a.Species)] or 0, RANK[G.rarOf(b.Species)] or 0
        if ra ~= rb then if fastest then return ra < rb end return ra > rb end
        return G.mult(a.Species) > G.mult(b.Species)
    end)
    local k = 1
    for slot = 1, (Cfg.Incubators and Cfg.Incubators.Count) or 6 do
        if unl[slot] and not inc[slot] and list[k] then
            local e = list[k]; k = k + 1
            local res = inv("LabRequest", "Incubate", { Slot = slot, Egg = e.Id })
            if okRes(res) then DINO.usedEgg[e.Id] = true end
            task.wait(0.25)
        end
    end
end
function DINO.hatch()
    local inc = G.json(L["Incubators"], {})
    for slot, s in pairs(inc) do
        if type(s) == "table" and tonumber(s.Ends) and s.Ends <= G.now() then
            local res = inv("LabRequest", "Hatch", tonumber(slot) or slot)
            if okRes(res) then
                S.st.hatched = S.st.hatched + 1
                DINO.after(res.creature)
            end
            task.wait(0.4)
        end
    end
end
function DINO.mutate()
    local cur = lp:GetAttribute("MutSpecies")
    if type(cur) == "string" and cur ~= "" then
        local ends = tonumber(lp:GetAttribute("MutEnds")) or 0
        if ends <= G.now() then
            local res = inv("MutationRequest", "Hatch")
            if okRes(res) then S.st.hatched = S.st.hatched + 1; DINO.after(res.creature); notify(L["Mutation hatched!"]) end
        end
        return
    end
    local pid = G.partnerId()
    local all = G.creatures()
    for _, key in ipairs(Cfg.MutationOrder or {}) do
        local mu = Cfg.Mutations and Cfg.Mutations[key]
        if mu and SHOP.spare() >= (mu.Coins or 0) then
            local ids, used = {}, {}
            for i, sp in ipairs(mu.Parents or {}) do
                local best, bv
                for _, c in ipairs(all) do
                    if c.Species == sp and c.Id ~= pid and not used[c.Id] and (on("mu_ranch") or c.Placed ~= true)
                        and not (on("pr_size") and (tonumber(c.Frac) or 0) >= 0.85) then
                        local inf = G.info(c, pid)
                        if inf.stage >= (mu.MinStage or 4) and (not bv or inf.value < bv) then best, bv = c, inf.value end
                    end
                end
                if not best then ids = nil; break end
                ids[i] = best.Id; used[best.Id] = true
            end
            if ids then
                local res = inv("MutationRequest", "Start", key, ids)
                if okRes(res) then notify(L["Mutation started · "] .. G.name(key)); return end
            end
        end
    end
end
function DINO.ranch()
    local pid = G.partnerId()
    local all = G.creatures()
    local placed, stored = {}, {}
    for _, c in ipairs(all) do
        if c.Id ~= pid then
            local inf = G.info(c, pid)
            if c.Placed == true then placed[#placed + 1] = { c = c, i = inf } else stored[#stored + 1] = { c = c, i = inf } end
        end
    end
    local waiting = {}
    for _, x in ipairs(stored) do if not x.i.grown then waiting[#waiting + 1] = x end end
    table.sort(waiting, function(a, b) if a.i.rank ~= b.i.rank then return a.i.rank > b.i.rank end return a.i.value > b.i.value end)
    local cap = Cfg.RanchCapacity or 8
    if on("rn_swap") and #waiting > 0 then
        for _, x in ipairs(placed) do
            if x.i.grown and #placed >= cap then
                if okRes(inv("RanchRequest", "Store", x.c.Id)) then
                    for j, y in ipairs(placed) do if y == x then table.remove(placed, j); break end end
                end
                task.wait(0.3)
                break
            end
        end
    end
    local free_ = cap - #placed
    for k = 1, math.min(free_, #waiting) do
        inv("RanchRequest", L["Place"], waiting[k].c.Id)
        task.wait(0.3)
    end
end
function DINO.pickFood(sp, food, fish)
    for _, m in ipairs(G.menu(sp)) do
        if m == "Fish" then
            if on("fd_fish") then
                local best, bp
                for id, n in pairs(fish) do
                    local d = Cfg.Fish and Cfg.Fish[id]
                    if (tonumber(n) or 0) > num("sx_keep", 0) and d and (not bp or d.Price < bp) then best, bp = id, d.Price end
                end
                if best then return best end
            end
        elseif (tonumber(food[m]) or 0) > 0 then
            return m
        end
    end
    return nil
end
function DINO.buyFood(item, have)
    local keep = num("fd_keep", 20)
    if have >= keep then return end
    local qty = (keep - have) >= 40 and 50 or 10
    local price = (DL.Foods and DL.Foods[item] and DL.Foods[item].Price) or 12
    if SHOP.spare() < price * qty then qty = 1 end
    if SHOP.spare() < price * qty then return end
    G.near("Bramble", function() return inv("FeedRequest", "Buy", item, qty) end)
end
function DINO.dinoPos(c)
    if c.Id == G.partnerId() then
        local pf = Workspace:FindFirstChild("FTD_Partners")
        local m = pf and pf:FindFirstChild("Partner_" .. lp.Name)
        if m then local ok, cf = pcall(m.GetPivot, m); if ok then return cf.Position end end
        return nil
    end
    local f = Workspace:FindFirstChild("FTD_Ranch")
    local m = f and f:FindFirstChild(tostring(c.Species) .. "_" .. tostring(c.Id))
    if m then local ok, cf = pcall(m.GetPivot, m); if ok then return cf.Position end end
    return nil
end
function DINO.feed()
    local pid = G.partnerId()
    local at = num("fd_at", 60) / 100
    local food, fish = G.json("Food", {}), G.json("Fish", {})
    if on("fd_buy") then
        local needs = {}
        for _, c in ipairs(G.creatures()) do
            if c.Placed == true or c.Id == pid then
                for _, m in ipairs(G.menu(c.Species)) do if m ~= "Fish" then needs[m] = true; break end end
            end
        end
        for item in pairs(needs) do DINO.buyFood(item, tonumber(food[item]) or 0) end
        food = G.json("Food", {})
    end
    local fedN, hungry = 0, 0
    for _, c in ipairs(G.creatures()) do
        if not RUNNING or not on("fd_on") then break end
        local inf = G.info(c, pid)
        if inf.active and not inf.grown and inf.fed < at then
            hungry = hungry + 1
            for _ = 1, 6 do
                local item = DINO.pickFood(c.Species, food, fish)
                if not item then break end
                local res = inv("RanchRequest", "Feed", c.Id, item)
                if not okRes(res) and why(res):lower():find("equip") and claimWait("feed", 6) then
                    local tool = G.foodTool(item)
                    local h = hum()
                    if tool and h then pcall(function() h:EquipTool(tool) end); task.wait(0.15) end
                    res = inv("RanchRequest", "Feed", c.Id, item)
                    free("feed")
                end
                if not okRes(res) and far(res) and claimWait("feed", 6) then
                    local p = DINO.dinoPos(c)
                    if p then land(p + Vector3.new(3, 0, 3), p); task.wait(0.25) end
                    res = inv("RanchRequest", "Feed", c.Id, item)
                    free("feed")
                end
                if not okRes(res) then break end
                fedN = fedN + 1
                if food[item] then food[item] = (tonumber(food[item]) or 1) - 1 elseif fish[item] then fish[item] = (tonumber(fish[item]) or 1) - 1 end
                if (tonumber(res.fed) or 1) >= 0.95 then break end
                task.wait(0.35)
            end
        end
    end
    setText(UI.fdState, hungry > 0 and (L["Feed · "] .. fedN .. L[" meals given"]) or L["Feed · everyone is full"])
end
function DINO.status()
    local inc, unl = G.json(L["Incubators"], {}), G.json("IncUnlocked", {})
    local open, used, nextEnd = 0, 0, nil
    for i = 1, (Cfg.Incubators and Cfg.Incubators.Count) or 6 do
        if unl[i] then
            open = open + 1
            local s = inc[i]
            if type(s) == "table" then
                used = used + 1
                local e = tonumber(s.Ends)
                if e and (not nextEnd or e < nextEnd) then nextEnd = e end
            end
        end
    end
    local all = G.creatures()
    local placed = G.placedCount()
    setText(UI.inState, string.format(L["Incubators %d/%d%s"], used, open, nextEnd and (L[" · next "] .. G.clock(nextEnd - G.now())) or ""))
    setText(UI.rnState, string.format(L["Ranch %d/%d · Storage %d"], placed, Cfg.RanchCapacity or 8, #all - placed))
    setText(UI.htLast, L["Last hatch · "] .. G.short(DINO.lastHatch, 22))
    local ms = lp:GetAttribute("MutSpecies")
    if type(ms) == "string" and ms ~= "" then
        setText(UI.muState, L["Mutation · "] .. G.clock((tonumber(lp:GetAttribute("MutEnds")) or 0) - G.now()))
    else
        setText(UI.muState, L["Mutation · idle"])
    end
end
function DINO.tick()
    if on("eg_trade") and SHOP.every("trade", 3) then DINO.trade() end
    if on("ht_on") and SHOP.every("hatch", 2) then DINO.hatch() end
    if on("in_on") and SHOP.every("incubate", 3) then DINO.incubate() end
    if on("mu_on") and SHOP.every("mutate", 10) then DINO.mutate() end
    if on("rn_fill") and SHOP.every("ranch", 8) then DINO.ranch() end
    if on("fd_on") and SHOP.every("feed", num("fd_every", 15)) then DINO.feed() end
    if SHOP.every("dstatus", 1) then DINO.status() end
    if SHOP.every("eggclean", 30) then DINO.usedEgg = {} end
end
local SELL = {}
function SELL.protected(sp, rar)
    local pr, ps = msel("pr_rar"), msel("pr_species")
    if pr and pr[rar] then return true end
    if ps and sp and ps[sp] then return true end
    return false
end
function SELL.call(kind, id, qty)
    return G.near("Ronald", function() return inv("SellRequest", kind, id, qty) end)
end
function SELL.gain(res)
    local c = type(res) == "table" and tonumber(res.coins)
    if c then S.st.sold = S.st.sold + c end
end
function SELL.tick()
    local total = 0
    if on("sf_on") then
        local pick = msel("sf_rar")
        local tradeOn, tradePick = on("eg_trade"), msel("eg_rar")
        for sp, n in pairs(G.fossils()) do
            local rar = G.rarOf(sp)
            local c = Cfg.Creatures and Cfg.Creatures[sp]
            if pick and pick[rar] and not SELL.protected(sp, rar) then
                local keep = 0
                if on("sf_keep") and c and not c.Marine and not c.Hybrid then
                    if tradeOn and (not tradePick or tradePick[rar]) then keep = n
                    elseif not tradeOn then keep = math.min(n, G.need(sp)) end
                end
                local q = n - keep
                if q > 0 then local res = SELL.call("Fossil", sp, q); if okRes(res) then SELL.gain(res); total = total + q end; task.wait(0.25) end
            end
        end
    end
    if on("sx_on") then
        local pick = msel("sx_rar")
        local keep = num("sx_keep", 0)
        for id, n in pairs(G.json("Fish", {})) do
            local d = Cfg.Fish and Cfg.Fish[id]
            local q = (tonumber(n) or 0) - keep
            if d and pick and pick[d.Rarity] and q > 0 and not SELL.protected(nil, d.Rarity) then
                local res = SELL.call("Fish", id, q); if okRes(res) then SELL.gain(res); total = total + q end; task.wait(0.25)
            end
        end
    end
    if on("se_on") then
        local pick = msel("se_rar")
        for sp, n in pairs((function() local o = {}; for _, e in ipairs(G.json("Eggs", {})) do if e.Species then o[e.Species] = (o[e.Species] or 0) + 1 end end; return o end)()) do
            local rar = G.rarOf(sp)
            if pick and pick[rar] and not SELL.protected(sp, rar) then
                local res = SELL.call("Egg", sp, n); if okRes(res) then SELL.gain(res); total = total + n end; task.wait(0.25)
            end
        end
    end
    if on("sd_on") then
        local pick = msel("sd_rar")
        local pid = G.partnerId()
        for _, c in ipairs(G.creatures()) do
            local rar = G.rarOf(c.Species)
            if c.Id ~= pid and pick and pick[rar] and not SELL.protected(c.Species, rar)
                and (on("sd_ranch") or c.Placed ~= true)
                and not (on("pr_size") and (tonumber(c.Frac) or 0) >= 0.85) then
                local inf = G.info(c, pid)
                if (not on("sd_elder") or inf.grown) then
                    local res = SELL.call("Dino", c.Id); if okRes(res) then SELL.gain(res); total = total + 1 end; task.wait(0.3)
                end
            end
        end
    end
    if total > 0 then setText(UI.slState, L["Sold "] .. total .. " · +" .. G.money(S.st.sold) .. L[" total"]) end
end
local MOVE = { saved = {}, boats = nil, ride = nil, rideFrom = nil, flyBV = nil }
function MOVE.apply()
    local h = hum()
    if h then
        if on("pl_ws") then
            if MOVE.saved.ws == nil then MOVE.saved.ws = h.WalkSpeed end
            if h.WalkSpeed ~= 0 or not on("fs_on") then h.WalkSpeed = num("pl_ws_v", 32) end
        elseif MOVE.saved.ws ~= nil then
            h.WalkSpeed = MOVE.saved.ws; MOVE.saved.ws = nil
        end
        if on("pl_jp") then
            if MOVE.saved.jp == nil then MOVE.saved.jp = h.JumpHeight end
            h.JumpHeight = num("pl_jp_v", 12)
        elseif MOVE.saved.jp ~= nil then
            h.JumpHeight = MOVE.saved.jp; MOVE.saved.jp = nil
        end
    end
    local bm = on("pl_boat") and num("pl_boat_v", 1.5) or 1
    if bm ~= 1 and not MOVE.boats then
        MOVE.boats = {}
        for k, b in pairs(Cfg.Boats or {}) do MOVE.boats[k] = { b.MaxSpeed, b.Accel } end
    end
    if MOVE.boats then
        for k, b in pairs(Cfg.Boats or {}) do
            local o = MOVE.boats[k]
            if o then b.MaxSpeed = o[1] * bm; b.Accel = (o[2] or 1) * math.min(bm, 2) end
        end
        if bm == 1 then MOVE.boats = nil end
    end
    local rm = on("pl_ride") and num("pl_ride_v", 1.5) or 1
    local rmt = Cfg.Partner and Cfg.Partner.RarityMult
    if rmt then
        if rm ~= 1 and not MOVE.ride then MOVE.ride = {}; for k, v in pairs(rmt) do MOVE.ride[k] = v end end
        if MOVE.ride then
            for k, v in pairs(MOVE.ride) do rmt[k] = v * rm end
            if rm == 1 then MOVE.ride = nil end
        end
    end
    if on("pl_rideany") then
        if MOVE.rideFrom == nil then MOVE.rideFrom = DL.RideFrom or 3 end
        DL.RideFrom = 1
    elseif MOVE.rideFrom ~= nil then
        DL.RideFrom = MOVE.rideFrom; MOVE.rideFrom = nil
    end
end
function MOVE.restore()
    local h = hum()
    if h and MOVE.saved.ws then h.WalkSpeed = MOVE.saved.ws end
    if h and MOVE.saved.jp then h.JumpHeight = MOVE.saved.jp end
    if MOVE.boats then for k, b in pairs(Cfg.Boats or {}) do local o = MOVE.boats[k]; if o then b.MaxSpeed = o[1]; b.Accel = o[2] end end end
    local rmt = Cfg.Partner and Cfg.Partner.RarityMult
    if MOVE.ride and rmt then for k, v in pairs(MOVE.ride) do rmt[k] = v end end
    if MOVE.rideFrom ~= nil then DL.RideFrom = MOVE.rideFrom end
end
onClean(MOVE.restore)
function MOVE.step()
    local r = hrp()
    if not r then return end
    if BOSS.hover and S.bossWant then
        r.AssemblyLinearVelocity = Vector3.zero
        r.CFrame = CFrame.new(BOSS.hover) * (r.CFrame - r.CFrame.Position)
        return
    end
    if on("pl_fly") then
        local cam = Workspace.CurrentCamera
        local h = hum()
        local dir = h and h.MoveDirection or Vector3.zero
        local up = 0
        if UserInputService:IsKeyDown(Enum.KeyCode.Space) then up = 1 elseif UserInputService:IsKeyDown(Enum.KeyCode.LeftControl) or UserInputService:IsKeyDown(Enum.KeyCode.Q) then up = -1 end
        local sp = num("pl_fly_v", 60)
        local v = Vector3.new(dir.X, 0, dir.Z) * sp + Vector3.new(0, up * sp, 0)
        if cam and dir.Magnitude > 0 then
            local look = cam.CFrame.LookVector
            if math.abs(look.Y) > 0.3 then v = v + Vector3.new(0, look.Y * sp * dir.Magnitude, 0) end
        end
        r.AssemblyLinearVelocity = v
    end
end
function MOVE.noclip()
    if not (on("pl_noclip") or (on("pl_fly") and on("pl_fly_noclip"))) then
        if MOVE.clipped then
            for p in pairs(MOVE.clipped) do pcall(function() if p.Parent then p.CanCollide = true end end) end
            MOVE.clipped = nil
        end
        return
    end
    local c = lp.Character; if not c then return end
    MOVE.clipped = MOVE.clipped or setmetatable({}, { __mode = "k" })
    for _, p in ipairs(c:GetDescendants()) do
        if p:IsA("BasePart") and p.CanCollide then p.CanCollide = false; MOVE.clipped[p] = true end
    end
end
