        local pick = msel("esp_islands")
        local f = Workspace:FindFirstChild("DigSites")
        local maxd = num("esp_range", 600)
        for _, m in ipairs(f and f:GetChildren() or {}) do
            local isl = m:GetAttribute("Island")
            if isl and (not pick or pick[isl]) and m:GetAttribute("Busy") ~= true then
                local ok, cf = pcall(m.GetPivot, m)
                if ok and (not from or maxd <= 0 or (cf.Position - from).Magnitude <= maxd) then
                    local d = from and math.floor((cf.Position - from).Magnitude) or 0
