    if on("esp_nests") then
        for _, id in ipairs((Cfg.Nests and Cfg.Nests.Order) or {}) do
            local site = Cfg.Nests.Sites[id]
            local m = NEST.model(id)
            local left = ((Cfg.Nests.Eggs or 4) - (tonumber(lp:GetAttribute("Nest_" .. id)) or 0))
            local sp, rar = m and m:GetAttribute("Species"), m and m:GetAttribute("Rarity")
            local txt = "Nest · " .. id .. (sp and (" · " .. G.name(sp)) or "") .. " · " .. left .. " left"
            ESP.mark("nest" .. id, site.Pos + Vector3.new(0, 6, 0), txt, rar and G.rcol(rar) or Color3.fromRGB(255, 180, 90))
        end
    end
    if on("esp_boss") and MB then
        local pose = BOSS.pose()
        if pose then
            local hp, mx = tonumber(FTD:GetAttribute("BossHP")) or 0, tonumber(FTD:GetAttribute("BossMaxHP")) or 1
            ESP.mark("boss", pose.Position + Vector3.new(0, 20, 0), "Mosasaurus · " .. math.floor(hp / math.max(1, mx) * 100) .. "%", Color3.fromRGB(255, 80, 110))
        end
    end
    for k, m in pairs(ESP.marks) do
        if not m.seen then pcall(function() m.part:Destroy() end); ESP.marks[k] = nil else m.seen = false end
    end
end
