local TP = {}
function TP.places()
    local out = { "My Ranch", "Home Plaza" }
    for _, isl in ipairs(Cfg.IslandOrder or {}) do out[#out + 1] = isl end
    for _, id in ipairs((Cfg.Nests and Cfg.Nests.Order) or {}) do out[#out + 1] = "Nest · " .. id end
    out[#out + 1] = "Boss Arena"
    for _, m in ipairs(G.npcModels()) do G.noteNPC(m) end
    local names = {}
    for n in pairs(G.NPC_NAMES) do names[#names + 1] = n end
    table.sort(names)
    for _, n in ipairs(names) do out[#out + 1] = n end
    return out
end
function TP.go(name)
    name = tostring(name or "")
    local map = Workspace:FindFirstChild("Map")
    if name == "My Ranch" then
        local p = NEST.homeSpot()
        if p then tp(p) else NEST.escape() end
        return true
    elseif name == "Home Plaza" then
        local pz = map and map:FindFirstChild("Plaza"); local ms = pz and pz:FindFirstChild("MainSpawn")
        if ms then tp(ms.Position + Vector3.new(0, 3.5, 0)) return true end
        local c = Cfg.Zones and Cfg.Zones.Home and Cfg.Zones.Home.Center
        if c then land(c) return true end
    elseif name == "Boss Arena" then
        local c = FTD:GetAttribute("BossCenter"); if typeof(c) ~= "Vector3" then c = MB and MB.Center end
        if c then tp(Vector3.new(c.X, (tonumber(Cfg.WaterY) or 0) + 3, c.Z + 120)) return true end
    elseif name:sub(1, 7) == "Nest · " then
        local site = Cfg.Nests and Cfg.Nests.Sites and Cfg.Nests.Sites[name:sub(8)]
        if site then land(site.Pos + Vector3.new(0, 0, 25), site.Pos) return true end
    elseif Cfg.Zones and Cfg.Zones[name] then
        local f = map and map:FindFirstChild(name)
        local c = (f and f:GetAttribute("Center")) or Cfg.Zones[name].Center
        local dock = f and f:GetAttribute("Dock")
        stream(c)
        local g, wet = groundAt(c)
        if g and not wet then tp(g + Vector3.new(0, 3.2, 0)) return true end
        if typeof(dock) == "Vector3" then land(dock) return true end
        land(c) return true
    else
        local base, dock = name:match("^(.-) · (.+)$")
        base = base or name
        local function find()
            for _, m in ipairs(G.npcModels()) do
                local n = tostring(m:GetAttribute("DisplayName") or m:GetAttribute("NPC"))
                if (n == base or m:GetAttribute("NPC") == base) and (not dock or m:GetAttribute("Dock") == dock) then
                    local ok, cf = pcall(m.GetPivot, m)
                    if ok then return cf end
                end
            end
        end
        local cf = find() or G.NPC_POS[name]
        if not cf then
            local isl = dock and map and map:FindFirstChild(dock)
            local c = isl and isl:GetAttribute("Center")
            if typeof(c) == "Vector3" then tp(Vector3.new(c.X, (tonumber(isl:GetAttribute("PlateauTop")) or 4) + 3.2, c.Z))
            else TP.go("Home Plaza") end
            for _ = 1, 25 do task.wait(0.2); cf = find(); if cf then break end end
        end
        if cf then tp(cf.Position + cf.LookVector * 5 + Vector3.new(0, 0.5, 0), cf.Position) return true end
    end
    return false
end
