function SPY.read(name)
    local p = Players:FindFirstChild(tostring(name or ""))
    if not p then return { "Pick a player" } end
    local cs = G.creatures(p)
    local pid = G.partnerId(p)
    local best, bv, placed = nil, 0, 0
    for _, c in ipairs(cs) do
        if c.Placed == true then placed = placed + 1 end
        local inf = G.info(c, pid)
        if inf.value > bv then best, bv = c, inf.value end
    end
    local eggs = #G.json("Eggs", {}, p)
    return {
        string.format("Coins %s · Lv %s", G.money(G.coins(p)), tostring(p:GetAttribute("Level") or "?")),
        string.format("Dinos %d (%d ranch) · Eggs %d", #cs, placed, eggs),
        best and ("Best · " .. G.rarOf(best.Species) .. " " .. G.name(best.Species)) or "Best · none",
        "Shovel · " .. tostring(p:GetAttribute("EquippedShovel") or "?") .. " · Boat " .. tostring(p:GetAttribute("EquippedBoat") or "?"),
    }
end
local PERF = { capped = false, noRender = false, pauseConn = nil }
function PERF.noPause(v)
    if PERF.pauseConn then pcall(function() PERF.pauseConn:Disconnect() end); PERF.pauseConn = nil end
    if not v then return end
    local ok, rg = pcall(function() return game:GetService("CoreGui"):FindFirstChild("RobloxGui") end)
    if not ok or not rg then return end
    local function kill(o) if o.Name == "CoreScripts/NetworkPause" then pcall(function() o:Destroy() end) end end
