section(L["Shop"], function()
    local Tab = Window:AddTab(L["Shop"], "gift")
    local AB = Tab:AddLeftGroupbox(L["Auto Buy"], "arrow-up")
    AB:AddToggle("sh_shovel", { Text = L["Auto Upgrade Shovel"], Default = false, Tooltip = L["Unlocks new islands"] })
    AB:AddToggle("sh_inc", { Text = L["Auto Buy Incubators"], Default = false })
    AB:AddToggle("sh_rod", { Text = L["Auto Buy Rod"], Default = false })
    AB:AddToggle("sh_clover", { Text = L["Auto Lucky Clover"], Default = false, Tooltip = L["Keeps 2x luck going"] })
    AB:AddToggle("sh_boat", { Text = L["Auto Upgrade Boat"], Default = false })
    AB:AddSlider("sh_reserve", { Text = L["Keep Coins"], Default = 0, Min = 0, Max = 500000, Rounding = 0, Tooltip = L["Never spends below this"] })
    local CB = Tab:AddLeftGroupbox(L["Codes"], "ticket")
    CB:AddInput("cd_code", { Default = "", Numeric = false, Finished = false, ClearTextOnFocus = false, Text = L["Code"], Placeholder = L["Type a code"] })
    UI.cdState = CB:AddLabel(L["Join the group for codes"], true)
    CB:AddButton({ Text = L["Redeem"], Func = function()
        task.spawn(function() setText(UI.cdState, SHOP.redeem(val("cd_code", ""))) end)
    end })
    CB:AddButton({ Text = L["Redeem Known Codes"], Func = function()
        task.spawn(function()
            local out = {}
            for _, c in ipairs(CONFIG.CODES) do out[#out + 1] = c .. ": " .. SHOP.redeem(c) end
            setText(UI.cdState, table.concat(out, "\n"))
        end)
    end })
    local OB = Tab:AddRightGroupbox(L["Open Anywhere"], "menu")
    local ctrls = lp:FindFirstChild("PlayerScripts") and lp.PlayerScripts:FindFirstChild("FTD_Controllers")
    local function open(mod, ...)
        local args = table.pack(...)
        local m = ctrls and ctrls:FindFirstChild(mod)
        if not m then notify(L["Not available"]); return end
        gcall(function()
            local ok, M = pcall(require, m)
            if ok and type(M) == "table" and type(M.Open) == "function" then M.Open(table.unpack(args, 1, args.n)) end
        end)
    end
    OB:AddButton({ Text = L["Sell Stall"], Func = function() open("SellUI") end })
    OB:AddButton({ Text = L["Shovel Shop"], Func = function() open("GearShop", "Shovels") end })
    OB:AddButton({ Text = L["Tackle Shop"], Func = function() open("GearShop", "Rods") end })
    OB:AddButton({ Text = L["Feed Shop"], Func = function() open("FeedShop") end })
    OB:AddButton({ Text = L["Boat Shop"], Func = function() open("BoatShop") end })
    OB:AddButton({ Text = L["Incubators"], Func = function() open("IncubatorRoom") end })
    OB:AddButton({ Text = L["Mutation Lab"], Func = function() open("MutationUI") end })
    local TB = Tab:AddRightGroupbox(L["Tutorial"], "fast-forward")
    TB:AddButton({ Text = L["Skip Tutorial"], Func = function()
        task.spawn(function() local res = inv("TutorialRequest", L["Skip"]); notify(okRes(res) and L["Tutorial skipped"] or G.short(why(res), 30)) end)
    end })
end)
