section(L["World"], function()
    local Tab = Window:AddTab(L["World"], "map")
    local TB = Tab:AddLeftGroupbox(L["Teleport"], "map-pin")
    TB:AddDropdown("tp_where", { Text = L["Place"], Values = TP.places(), Default = "My Ranch", Searchable = true })
    TB:AddButton({ Text = L["Teleport"], Func = function()
        local w = val("tp_where", "My Ranch")
        if TP.busy then return end
        TP.busy = true
        task.spawn(function()
            local ok = pcall(TP.go, w)
            TP.busy = false
            if not ok then notify(L["Not loaded yet"]) end
        end)
    end })
    TB:AddButton({ Text = L["Refresh Places"], Func = function() pcall(function() Opt.tp_where:SetValues(TP.places()) end) end })
    local EB = Tab:AddLeftGroupbox(L["ESP"], "eye")
    EB:AddToggle("esp_sites", { Text = L["Dig Sites"], Default = false })
    local sd = EB:AddDependencyBox()
    sd:AddDropdown("esp_islands", { Text = L["Islands"], Values = LISTS.islands, Multi = true, AllowNull = true, Tooltip = L["Empty = all"] })
    sd:AddSlider("esp_range", { Text = L["Range"], Default = 600, Min = 0, Max = 3000, Rounding = 0, Suffix = L[" studs"], Tooltip = L["0 = whole map"] })
    sd:SetupDependencies({ { Toggles.esp_sites, true } })
    EB:AddToggle("esp_nests", { Text = L["Nests"], Default = false })
    EB:AddToggle("esp_boss", { Text = "Boss", Default = false })
    local PB = Tab:AddRightGroupbox(L["Player Spy"], "users")
    PB:AddDropdown("spy_p", { Text = L["Player"], Values = SPY.list(), AllowNull = true, Searchable = true })
    UI.spy1 = PB:AddLabel("-")
    UI.spy2 = PB:AddLabel("-")
    UI.spy3 = PB:AddLabel("-")
    UI.spy4 = PB:AddLabel("-")
    PB:AddButton({ Text = L["Refresh Players"], Func = function() pcall(function() Opt.spy_p:SetValues(SPY.list()) end) end })
    local function refresh()
        pcall(function()
            local cur = val("spy_p")
            Opt.spy_p:SetValues(SPY.list())
            if cur and Players:FindFirstChild(cur) then Opt.spy_p:SetValue(cur) end
        end)
    end
    track(Players.PlayerAdded:Connect(refresh))
    track(Players.PlayerRemoving:Connect(function() task.defer(refresh) end))
end)
