    S.bossWant = false
end)
task.spawn(DIG.loop)
task.spawn(FISH.loop)
task.spawn(NEST.loop)
task.spawn(BOSS.loop)
task.spawn(function()
    while RUNNING do
        pcall(MOVE.apply)
        pcall(PERF.tick)
        if lp:GetAttribute("DataLoaded") ~= false then
            pcall(SHOP.tick)
            pcall(DINO.tick)
            if (on("sf_on") or on("sx_on") or on("se_on") or on("sd_on")) and SHOP.every("sell", num("sl_every", 20)) then pcall(SELL.tick) end
        end
        if SHOP.every("tplist", 10) and Opt and Opt.tp_where then
            local n = 0
            for _ in pairs(G.NPC_NAMES) do n = n + 1 end
            if n ~= TP.known then
                TP.known = n
                pcall(function()
                    local cur = Opt.tp_where.Value
                    Opt.tp_where:SetValues(TP.places())
                    if cur then Opt.tp_where:SetValue(cur) end
                end)
            end
        end
        if not S.st.coins0 then S.st.coins0 = G.coins() end
        local mins = math.max(1 / 60, (os.clock() - S.st.t0) / 60)
        local gained = G.coins() - (S.st.coins0 or G.coins())
        setText(UI.ssCoins, string.format(L["Coins %s · +%s (%s/h)"], G.money(G.coins()), G.money(gained), G.money(gained / mins * 60)))
        setText(UI.ssDig, string.format(L["Digs %d · Fossils %d"], S.st.digs, S.st.fossils))
        setText(UI.ssDino, string.format(L["Eggs %d · Hatched %d"], S.st.eggs + S.st.nests + S.st.seaEggs, S.st.hatched))
        setText(UI.ssSea, string.format(L["Fish %d · Nests %d · Boss %d"], S.st.fish, S.st.nests, S.st.boss))
        if val("spy_p") then
            local l = SPY.read(val("spy_p"))
            setText(UI.spy1, l[1] or "-"); setText(UI.spy2, l[2] or "-"); setText(UI.spy3, l[3] or "-"); setText(UI.spy4, l[4] or "-")
        end
        if not on("dg_on") then setText(UI.dgState, L["Dig · off"]) end
        if not on("fs_on") then setText(UI.fsState, L["Fish · off"]) end
        if not on("ns_on") then setText(UI.nsState, L["Nests · off"]) end
        if not on("fd_on") then setText(UI.fdState, L["Feed · off"]) end
        task.wait(1)
    end
end)
task.spawn(function()
    while RUNNING do
        pcall(ESP.tick)
        task.wait(0.5)
    end
end)
